CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(40) NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_roles (user_id uuid NOT NULL REFERENCES users(id), role_id uuid NOT NULL REFERENCES roles(id), effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, PRIMARY KEY(user_id,role_id,effective_from), CHECK(effective_to IS NULL OR effective_to>effective_from));
CREATE TABLE programs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(30) NOT NULL UNIQUE, name text NOT NULL, workflow_type varchar(10) NOT NULL CHECK(workflow_type IN('ONE_LEVEL','TWO_LEVEL')), self_service_mode varchar(20) CHECK(self_service_mode IN('SCHOOL_MANAGED','STUDENT_MANAGED','HYBRID')), self_service_min_grade smallint NOT NULL DEFAULT 10 CHECK(self_service_min_grade BETWEEN 1 AND 12), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE students (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_code varchar(30) NOT NULL UNIQUE, full_name varchar(150) NOT NULL, date_of_birth date NOT NULL CHECK(date_of_birth<=CURRENT_DATE), program_id uuid NOT NULL REFERENCES programs(id), current_school_id uuid NOT NULL REFERENCES schools(id), grade_level_current smallint CHECK(grade_level_current BETWEEN 1 AND 12), status varchar(30) NOT NULL DEFAULT 'ACTIVE', status_notes text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(status NOT IN('DROPPED_OUT','SCHOLARSHIP_STOPPED','UNREACHABLE') OR status_notes IS NOT NULL));
CREATE INDEX students_scope_idx ON students(current_school_id,program_id,status);
CREATE TABLE student_identity (student_id uuid PRIMARY KEY REFERENCES students(id), ciphertext bytea NOT NULL, key_version integer NOT NULL, identity_hmac char(64) NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE student_school_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES students(id),school_id uuid NOT NULL REFERENCES schools(id),effective_from date NOT NULL,effective_to date,CHECK(effective_to IS NULL OR effective_to>effective_from),EXCLUDE USING gist(student_id WITH =,daterange(effective_from,effective_to,'[)') WITH &&));
CREATE TABLE academic_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),program_id uuid NOT NULL REFERENCES programs(id),code varchar(30) NOT NULL,due_at timestamptz NOT NULL,timezone varchar(40) NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',workflow_type varchar(10) NOT NULL CHECK(workflow_type IN('ONE_LEVEL','TWO_LEVEL')),version integer NOT NULL DEFAULT 1,UNIQUE(program_id,code));
CREATE TABLE documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),object_key text NOT NULL UNIQUE,checksum char(64) NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1 AND 10485760),mime_type text NOT NULL,scan_status varchar(10) NOT NULL CHECK(scan_status IN('PENDING','CLEAN','INFECTED','ERROR')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document_links(document_id uuid NOT NULL REFERENCES documents(id),owner_type varchar(40) NOT NULL,owner_id uuid NOT NULL,purpose varchar(40) NOT NULL,PRIMARY KEY(document_id,owner_type,owner_id,purpose));
CREATE TABLE academic_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES students(id),period_id uuid NOT NULL REFERENCES academic_periods(id),type varchar(30) NOT NULL,status varchar(30) NOT NULL CHECK(status IN('DRAFT','SCHOOL_REVIEW','PROGRAM_REVIEW','RETURNED','REJECTED','APPROVED','LOCKED')),current_version_no integer NOT NULL DEFAULT 0,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(student_id,period_id,type));
CREATE TABLE submission_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submission_id uuid NOT NULL REFERENCES academic_submissions(id),version_no integer NOT NULL,payload_json jsonb NOT NULL,submitted_at timestamptz NOT NULL DEFAULT now(),UNIQUE(submission_id,version_no));
CREATE TABLE review_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submission_id uuid NOT NULL REFERENCES academic_submissions(id),level smallint NOT NULL CHECK(level IN(1,2)),assignee_id uuid REFERENCES users(id),reviewer_id uuid REFERENCES users(id),status varchar(20) NOT NULL CHECK(status IN('OPEN','APPROVED','RETURNED','REJECTED','CANCELLED')),reason_code varchar(50),note text,due_at timestamptz NOT NULL,version integer NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX review_active_level_idx ON review_tasks(submission_id,level) WHERE status='OPEN';
CREATE TABLE student_bank_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES students(id),account_name_ciphertext bytea NOT NULL,account_number_ciphertext bytea NOT NULL,account_hmac char(64) NOT NULL,key_version integer NOT NULL,bank_code varchar(20) NOT NULL,status varchar(20) NOT NULL CHECK(status IN('PENDING_REVIEW','VALIDATED','REJECTED')),effective_from timestamptz NOT NULL DEFAULT now(),effective_to timestamptz,version integer NOT NULL DEFAULT 1,CHECK(effective_to IS NULL OR effective_to>effective_from));
CREATE UNIQUE INDEX bank_active_student_idx ON student_bank_accounts(student_id) WHERE effective_to IS NULL;
CREATE TABLE manual_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),student_id uuid NOT NULL REFERENCES students(id),period_id uuid NOT NULL REFERENCES academic_periods(id),transfer_type varchar(30) NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>=0),currency char(3) NOT NULL CHECK(currency IN('VND','USD')),transferred_at timestamptz,reference varchar(100),status varchar(30) NOT NULL CHECK(status IN('PENDING_TRANSFER','AWAITING_CONFIRMATION','RECEIVED','NOT_RECEIVED','UNDER_INVESTIGATION','CLOSED','CORRECTED')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX transfer_active_obligation_idx ON manual_transfers(student_id,period_id,transfer_type) WHERE status NOT IN('CLOSED','CORRECTED');
CREATE TABLE transfer_confirmations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transfer_id uuid NOT NULL REFERENCES manual_transfers(id),student_id uuid NOT NULL REFERENCES students(id),result varchar(20) NOT NULL CHECK(result IN('RECEIVED','NOT_RECEIVED')),note text,confirmed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE transfer_corrections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),original_id uuid NOT NULL UNIQUE REFERENCES manual_transfers(id),replacement_id uuid NOT NULL UNIQUE REFERENCES manual_transfers(id),reason_code varchar(50) NOT NULL,reason text NOT NULL,approved_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(original_id<>replacement_id));
CREATE TABLE extension_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),obligation_id uuid NOT NULL,requested_by uuid NOT NULL REFERENCES users(id),reason text NOT NULL,proposed_due_at timestamptz NOT NULL,status varchar(20) NOT NULL CHECK(status IN('REQUESTED','APPROVED','REJECTED','CANCELLED')),decided_by uuid REFERENCES users(id),decided_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX extension_open_idx ON extension_requests(obligation_id) WHERE status='REQUESTED';
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),type varchar(60) NOT NULL,payload jsonb NOT NULL,resource_type varchar(40),resource_id uuid,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notification_inbox_idx ON notifications(user_id,read_at,created_at DESC);
CREATE TABLE notification_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),notification_id uuid NOT NULL REFERENCES notifications(id),channel varchar(10) NOT NULL CHECK(channel IN('IN_APP','EMAIL')),locale_used varchar(10) NOT NULL CHECK(locale_used IN('vi-VN','en-US')),status varchar(20) NOT NULL,attempts integer NOT NULL DEFAULT 0,sent_at timestamptz);
CREATE TABLE retention_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),data_category varchar(50) NOT NULL,retain_for_days integer NOT NULL CHECK(retain_for_days>0),action varchar(20) NOT NULL CHECK(action IN('ANONYMIZE','PURGE')),version integer NOT NULL,effective_from timestamptz NOT NULL,approved_by uuid NOT NULL REFERENCES users(id),UNIQUE(data_category,version));
CREATE TABLE legal_holds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_type varchar(40) NOT NULL,subject_ref text NOT NULL,reason text NOT NULL,approved_by uuid NOT NULL REFERENCES users(id),effective_at timestamptz NOT NULL,released_at timestamptz);
CREATE TABLE consent_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),policy_type varchar(40) NOT NULL,version integer NOT NULL,locale varchar(10) NOT NULL CHECK(locale IN('vi-VN','en-US')),content_hash char(64) NOT NULL,published_at timestamptz NOT NULL,UNIQUE(policy_type,version,locale));
CREATE TABLE consent_acceptances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),policy_id uuid NOT NULL REFERENCES consent_policies(id),student_id uuid NOT NULL REFERENCES students(id),accepted_by uuid NOT NULL REFERENCES users(id),accepted_at timestamptz NOT NULL,withdrawn_at timestamptz,evidence_json_redacted jsonb NOT NULL);

